static int search(int *nums, int lo, int hi) {
  if (lo > hi) return -1;
  int mid = lo + (hi - lo) / 2;
  if (nums[mid] == mid) return mid;
  int leftHi = mid - 1 < nums[mid] ? mid - 1 : nums[mid];
  int res = search(nums, lo, leftHi);
  if (res != -1) return res;
  int rightLo = mid + 1 > nums[mid] ? mid + 1 : nums[mid];
  return search(nums, rightLo, hi);
}

int findMagicIndex(int *nums, int numsSize) {
  return search(nums, 0, numsSize - 1);
}

class Solution {
  int search(vector<int> &nums, int lo, int hi) {
    if (lo > hi) return -1;
    int mid = lo + (hi - lo) / 2;
    if (nums[mid] == mid) return mid;
    int res = search(nums, lo, min(mid - 1, nums[mid]));
    if (res != -1) return res;
    return search(nums, max(mid + 1, nums[mid]), hi);
  }

public:
  int findMagicIndex(vector<int> &nums) { return search(nums, 0, nums.size() - 1); }
};

func findMagicIndex(nums []int) int {
