			return -1
		}
		mid := lo + (hi-lo)/2
		if nums[mid] == mid {
			return mid
		}
		leftHi := mid - 1
		if nums[mid] < leftHi {
			leftHi = nums[mid]
		}
		if res := search(lo, leftHi); res != -1 {
			return res
		}
		rightLo := mid + 1
		if nums[mid] > rightLo {
