}

class Solution {
  private int search(int[] nums, int lo, int hi) {
    if (lo > hi) return -1;
    int mid = lo + (hi - lo) / 2;
    if (nums[mid] == mid) return mid;
    int res = search(nums, lo, Math.min(mid - 1, nums[mid]));
    if (res != -1) return res;
    return search(nums, Math.max(mid + 1, nums[mid]), hi);
  }

  public int findMagicIndex(int[] nums) {
    return search(nums, 0, nums.length - 1);
  }
}

class Solution:
    def findMagicIndex(self, nums: List[int]) -> int:
        def search(lo: int, hi: int) -> int:
            if lo > hi:
                return -1
            mid = (lo + hi) // 2
            if nums[mid] == mid:
                return mid
            res = search(lo, min(mid - 1, nums[mid]))
            if res != -1:
                return res
            return search(max(mid + 1, nums[mid]), hi)

        return search(0, len(nums) - 1)

impl Solution {
  pub fn find_magic_index(nums: Vec<i32>) -> i32 {
    fn search(nums: &[i32], lo: i32, hi: i32) -> i32 {
      if lo > hi {
        return -1;
      }
      let mid = lo + (hi - lo) / 2;
      if nums[mid as usize] == mid {
        return mid;
      }
      let left_hi = (mid - 1).min(nums[mid as usize]);
      let res = search(nums, lo, left_hi);
      if res != -1 {
        return res;
      }
      search(nums, (mid + 1).max(nums[mid as usize]), hi)
    }
    search(&nums, 0, nums.len() as i32 - 1)
  }
}

const findMagicIndex = (nums: number[]): number => {
  const search = (lo: number, hi: number): number => {
    if (lo > hi) return -1;
    const mid = Math.floor((lo + hi) / 2);
    if (nums[mid] === mid) return mid;
    const res = search(lo, Math.min(mid - 1, nums[mid]));
    if (res !== -1) return res;
    return search(Math.max(mid + 1, nums[mid]), hi);
  };
  return search(0, nums.length - 1);
};
